import FunctionTree, {
  sequence,
  parallel,
  FunctionTreeExecutionError,
  Provider,
} from './'
import assert from 'assert'

describe('FunctionTree', () => {
  it('should create a function tree extending event emitter', () => {
    const ft = new FunctionTree({})

    assert.strictEqual(typeof ft.on, 'function')
    assert.strictEqual(typeof ft.once, 'function')
    assert.strictEqual(typeof ft.off, 'function')
  })
  it('should throw when passing wrong argument', () => {
    assert.throws(() => new FunctionTree([]))
  })
  it('should run with function argument', () => {
    const ft = new FunctionTree()

    ft.run(() => {
      assert.ok(true)
    })
  })
  it('should run with array argument', () => {
    const ft = new FunctionTree()

    ft.run([
      () => {
        assert.ok(true)
      },
    ])
  })
  it('should throw when there is no tree', () => {
    const ft = new FunctionTree()
    assert.throws(
      () => {
        ft.run()
      },
      (err) => {
        if (err instanceof Error) {
          return (
            err.message ===
            'function-tree - You did not pass in a function tree'
          )
        }
      }
    )
  })
  it('should run sequence and parallel', () => {
    const ft = new FunctionTree()

    ft.run(
      sequence([
        () => {
          assert.ok(true)
        },
      ])
    )

    ft.run(
      parallel([
        () => {
          assert.ok(true)
        },
      ])
    )
  })
  it('should set name of execution based on explicit, sequence name or id', () => {
    const ft = new FunctionTree()

    ft.run([
      ({ execution }) => {
        assert.ok(execution.name)
      },
    ])
    ft.run('foo', [
      ({ execution }) => {
        assert.strictEqual(execution.name, 'foo')
      },
    ])
    ft.run(
      sequence('bar', [
        ({ execution }) => {
          assert.strictEqual(execution.name, 'bar')
        },
      ])
    )
  })
  it('should emit execution events in correct order', () => {
    let eventsCount = 0
    const ft = new FunctionTree()

    ft.once('start', function () {
      eventsCount++
      assert.strictEqual(eventsCount, 1)
    })
    ft.once('functionStart', function () {
      eventsCount++
      assert.strictEqual(eventsCount, 2)
      ft.once('functionStart', function () {
        eventsCount++
        assert.strictEqual(eventsCount, 4)
      })
    })
    ft.once('functionEnd', function () {
      eventsCount++
      assert.strictEqual(eventsCount, 3)
      ft.once('functionEnd', function () {
        eventsCount++
        assert.strictEqual(eventsCount, 5)
      })
    })
    ft.on('end', function () {
      eventsCount++
      assert.strictEqual(eventsCount, 6)
    })
    ft.run([function actionA() {}, function actionB() {}])
  })
  it('should pass action and payload on action events', () => {
    const ft = new FunctionTree()

    ft.once('functionStart', function (execution, functionDetails, payload) {
      assert.ok(execution.id)
      assert.strictEqual(functionDetails.functionIndex, 0)
      assert.deepStrictEqual(payload, { foo: 'bar' })
    })
    ft.once('functionEnd', function (execution, functionDetails, payload) {
      assert.ok(execution.id)
      assert.strictEqual(functionDetails.functionIndex, 0)
      assert.deepStrictEqual(payload, { foo: 'bar' })
    })
    ft.run([() => {}], {
      foo: 'bar',
    })
  })
  it('should indicate parallel execution on function', () => {
    const ft = new FunctionTree()

    ft.once('functionStart', function (_execution, _functionDetails) {
      assert.ok(true)
    })
    ft.run([parallel([() => {}, () => {}])])
  })
  it('should pass final payload on end event', () => {
    const ft = new FunctionTree()
    ft.once('end', (_execution, payload) => {
      assert.deepStrictEqual(payload, { foo: 'bar', bar: 'foo' })
    })
    ft.run(
      [
        () => {
          return { bar: 'foo' }
        },
      ],
      { foo: 'bar' }
    )
  })

  it('should be able to reuse existing tree', (done) => {
    function actionA({ path }) {
      assert.ok(true)
      return path.success()
    }

    function actionB({ path }) {
      assert.ok(true)
      return path.success()
    }

    function actionC() {
      assert.ok(true)
    }

    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        success: [
          actionB,
          {
            success: [actionC],
          },
        ],
      },
    ]

    ft.run(tree, () => {
      ft.run(tree, () => {
        done()
      })
    })
  })
  it('should give error when path and no path returned', (done) => {
    function actionA() {
      return {
        foo: 'bar',
      }
    }

    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        success: [],
      },
    ]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.ok(error.message.match(/needs to be a path of either success/))
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should give error when path and no path returned with Promise', (done) => {
    function actionA() {
      return Promise.resolve({ foo: 'bar' })
    }

    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        success: [],
      },
    ]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.ok(error.message.match(/needs to be a path of either success/))
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should give error when function returns invalid result', (done) => {
    function actionA() {
      return 'bar'
    }

    const ft = new FunctionTree()
    const tree = [actionA]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.strictEqual(
        error.message,
        'The result "bar" from function actionA is not a valid result'
      )
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should give error when promise function returns invalid result', (done) => {
    function actionA() {
      return Promise.resolve('bar')
    }

    const ft = new FunctionTree()
    const tree = [actionA]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.strictEqual(
        error.message,
        'The result "bar" from function actionA is not a valid result'
      )
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should give error when promise function rejects without a path', (done) => {
    function actionA() {
      return Promise.reject({ foo: 'bar' })
    }

    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        success: [],
      },
    ]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.ok(error.message.match(/needs to be a path of either success/))
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should continue when promise function rejects with a valid result', (done) => {
    function actionA() {
      return Promise.reject({ foo: 'bar' })
    }

    const ft = new FunctionTree()
    const tree = [actionA]
    ft.once('end', (execution, finalPayload) => {
      assert.deepStrictEqual(finalPayload, {
        foo: 'bar',
      })
      done()
    })
    ft.run(tree)
  })
  it('should continue when promise function rejects with a valid path', (done) => {
    function actionA({ path }) {
      return Promise.reject(path.success({ foo: 'bar' }))
    }

    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        success: [],
      },
    ]
    ft.once('end', (execution, finalPayload) => {
      assert.deepStrictEqual(finalPayload, {
        foo: 'bar',
      })
      done()
    })
    ft.run(tree)
  })
  it('should give error when promise function rejects with an invalid result', (done) => {
    function actionA() {
      return Promise.reject('bar')
    }

    const ft = new FunctionTree()
    const tree = [actionA]

    ft.once('error', (error) => {
      assert.ok(error instanceof FunctionTreeExecutionError)
      assert.strictEqual(
        error.message,
        'The result "bar" from function actionA is not a valid result'
      )
      done()
    })
    ft.run(tree).catch(() => {})
  })
  it('should throw when given path is not defined', (done) => {
    function actionA({ path }) {
      return path.otherwise()
    }
    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        true: [],
        false: [],
      },
    ]
    ft.run(tree, {
      foo: 'bar',
    }).catch((error) => {
      assert.ok(error)
      done()
    })
  })
  it('should provide unique index to functions, even though the same', () => {
    function actionA({ verify }) {
      verify.check()
    }
    let count = 0
    const ft = new FunctionTree({
      verify: new Provider({
        check() {
          if (count === 0) {
            assert.strictEqual(this.context.functionDetails.functionIndex, 0)
          } else {
            assert.strictEqual(this.context.functionDetails.functionIndex, 1)
          }

          count++
        },
      }),
    })
    const tree = [actionA, actionA]
    ft.run(tree)
  })
  it('should emit branchStart and branchEnd events', () => {
    let branchStartCount = 0
    let branchEndCount = 0
    function actionA({ path }) {
      return path.test()
    }
    function actionB() {}
    function actionC() {}
    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        test: [actionB],
      },
      actionA,
      {
        test: [actionB],
      },
      actionC,
    ]
    ft.on('pathStart', () => {
      branchStartCount++
    })
    ft.on('pathEnd', () => {
      branchEndCount++
    })
    ft.run(tree)
    assert(branchStartCount, 2)
    assert(branchEndCount, 2)
  })
  it('should pass correct props on empty paths', () => {
    function actionA({ path }) {
      return path.true()
    }
    function actionB({ props }) {
      assert.deepStrictEqual(props, { foo: 'bar' })
    }
    const ft = new FunctionTree()
    const tree = [
      actionA,
      {
        true: [],
        false: [],
      },
      actionB,
    ]
    ft.run(tree, {
      foo: 'bar',
    })
  })
  it('should emit parallel events', (done) => {
    function actionA() {
      return Promise.resolve({ bar: 'baz' })
    }
    function actionB() {
      return Promise.resolve()
    }
    const ft = new FunctionTree()
    const tree = [[actionA, actionB]]
    ft.once(
      'parallelStart',
      (execution, currentPayload, functionsToResolve) => {
        assert.ok(execution)
        assert.deepStrictEqual(currentPayload, {
          foo: 'bar',
        })
        assert.strictEqual(functionsToResolve, 2)
      }
    )
    ft.once(
      'parallelProgress',
      (execution, currentPayload, functionsResolving) => {
        assert.ok(execution)
        assert.deepStrictEqual(currentPayload, {
          foo: 'bar',
          bar: 'baz',
        })
        assert.strictEqual(functionsResolving, 1)
      }
    )
    ft.once('parallelEnd', (execution, currentPayload, functionsResolved) => {
      assert.ok(execution)
      assert.deepStrictEqual(currentPayload, {
        foo: 'bar',
      })
      assert.strictEqual(functionsResolved, 2)
    })
    ft.once('end', (execution, finalPayload) => {
      assert.deepStrictEqual(finalPayload, {
        foo: 'bar',
        bar: 'baz',
      })
      done()
    })

    ft.run(tree, {
      foo: 'bar',
    })
  })
  it('should run functions in parallel', (done) => {
    const results = []
    function funcA() {
      return Promise.resolve().then(() => {
        results.push('A')
      })
    }
    function funcB() {
      results.push('B')
    }
    const ft = new FunctionTree()
    const tree = [parallel([funcA, funcB])]

    ft.once('end', () => {
      assert.deepStrictEqual(results, ['B', 'A'])
      done()
    })

    ft.run(tree)
  })
  it('should run grouped functions sequencially inside parallel', (done) => {
    const results = []
    function funcA() {
      return Promise.resolve().then(() => {
        results.push('A')
      })
    }
    function funcB() {
      results.push('B')
    }
    const group = [
      function funC() {
        return Promise.resolve().then(() => {
          results.push('C')
        })
      },
      function funcD() {
        results.push('D')
      },
    ]
    const ft = new FunctionTree()
    const tree = [parallel([funcA, funcB, group])]

    ft.once('end', () => {
      assert.deepStrictEqual(results, ['B', 'A', 'C', 'D'])
      done()
    })

    ft.run(tree)
  })
  it('should run grouped functions parallelly inside parallel', (done) => {
    const results = []
    function funcA() {
      return Promise.resolve().then(() => {
        results.push('A')
      })
    }
    function funcB() {
      results.push('B')
    }
    const group = parallel([
      function funC() {
        return Promise.resolve().then(() => {
          results.push('C')
        })
      },
      function funcD() {
        results.push('D')
      },
    ])
    const group2 = parallel([
      function funcE() {
        results.push('E')
      },
    ])
    const ft = new FunctionTree()
    const tree = [parallel([funcA, funcB, group, group2])]

    ft.once('end', () => {
      assert.deepStrictEqual(results, ['B', 'E', 'A', 'C', 'D'])
      done()
    })

    ft.run(tree)
  })
  it('should run functions after sequence', (done) => {
    let executedCount = 0
    const ft = new FunctionTree()

    function funcA() {
      executedCount++
    }
    function funcB() {
      executedCount++
    }
    function funcC() {
      executedCount++
    }

    const tree = [[funcA, funcB], funcC]

    ft.once('end', () => {
      assert.strictEqual(executedCount, 3)
      done()
    })

    ft.run(tree)
  })
  it('should not continue async execution when error thrown', (done) => {
    let executedCount = 0
    const ft = new FunctionTree()

    function funcA({ path }) {
      return Promise.resolve(path.test())
    }
    function funcB() {
      throw new Error('foo')
    }
    function funcC() {
      executedCount++
    }

    const tree = parallel([
      funcA,
      {
        test: funcC,
      },
      funcB,
    ])

    ft.run(tree).catch(() => {
      setTimeout(() => {
        assert.strictEqual(executedCount, 0)
        done()
      })
    })
  })
  it('should add stuff to context by passing in an object', (done) => {
    const ft = new FunctionTree({
      foo: {
        bar() {
          return 'bar'
        },
      },
    })

    ft.run([
      function (context) {
        assert.ok(context.foo.bar(), 'bar')
        done()
      },
    ])
  })
  it('should indicate async execution', (done) => {
    const ft = new FunctionTree()

    ft.run([
      function (context) {
        assert.ok(!context.execution.isAsync)
        return Promise.resolve()
      },
      function (context) {
        assert.ok(context.execution.isAsync)
        done()
      },
    ])
  })

  it('should run functions in parallel when returned from a path', () => {
    const results = []
    const ft = new FunctionTree()

    // Define functions for testing
    function asyncAction() {
      return Promise.resolve().then(() => {
        results.push('async')
      })
    }

    function syncAction() {
      results.push('sync')
    }

    // Test execution with path - parallel should work in this context
    const tree = [
      function actionWithPath({ path }) {
        return path.test()
      },
      {
        test: parallel([asyncAction, syncAction]),
      },
    ]

    return ft.run(tree).then(() => {
      // If parallel execution works correctly, sync action should complete
      // before the async action - proving parallel execution
      assert.deepStrictEqual(
        results,
        ['sync', 'async'],
        'Actions should execute in parallel when in a path'
      )
    })
  })

  it('should maintain parallel execution in different contexts', () => {
    const results = []
    const ft = new FunctionTree()

    // Actions for testing
    function asyncAction() {
      return Promise.resolve().then(() => {
        results.push('async')
      })
    }

    function syncAction() {
      results.push('sync')
    }

    // Test different ways of using parallel primitives
    const tree = [
      // Direct parallel usage
      parallel([asyncAction, syncAction]),

      // Path returning parallel
      function pathAction({ path }) {
        return path.test()
      },
      {
        test: parallel([asyncAction, syncAction]),
      },

      // Path with nested structures
      function nestedAction({ path }) {
        return path.nested()
      },
      {
        nested: [parallel([asyncAction, syncAction])],
      },
    ]

    return ft.run(tree).then(() => {
      // We should have 6 entries - 3 pairs of 'sync', 'async'
      // Each parallel execution should maintain order with sync before async
      assert.strictEqual(results.length, 6, 'All actions should have executed')

      // Check the pattern of results - every odd index should be 'sync'
      // and every even index should be 'async'
      for (let i = 0; i < results.length; i += 2) {
        assert.strictEqual(
          results[i],
          'sync',
          `Result at index ${i} should be 'sync'`
        )
        assert.strictEqual(
          results[i + 1],
          'async',
          `Result at index ${i + 1} should be 'async'`
        )
      }
    })
  })
})
